import {readFile} from 'node:fs/promises';
import {randomUUID} from 'node:crypto';
import {fixtureERP,esquemaERP,ERP_PASSWORD,ERP_ORIGIN} from './erp-api.mjs';
import {crearApi} from '../../src/http/api.mjs';
export {ERP_PASSWORD,ERP_ORIGIN};
export async function esquemaCentro(pool){await esquemaERP(pool);for(const n of ['001_snapshot_staging.sql','005_migracion_operativa.sql','006_conteos_comparten_origen.sql','013_centro_mando.sql'])for(const sql of (await readFile(new URL('../../sql/'+n,import.meta.url),'utf8')).replace(/^--.*$/gm,'').split(';').map(s=>s.trim()).filter(Boolean))await pool.query(sql);const [[r]]=await pool.query("SELECT COUNT(*) n FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='ims_cm_perfil' AND COLUMN_NAME='rol_wms'");if(!Number(r.n))await pool.query("ALTER TABLE ims_cm_perfil ADD COLUMN rol_wms VARCHAR(20) NOT NULL DEFAULT 'AUDITOR'");const [[a]]=await pool.query("SELECT COUNT(*) n FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='ims_cm_perfil' AND COLUMN_NAME='activacion_pendiente'");if(!Number(a.n))await pool.query("ALTER TABLE ims_cm_perfil ADD COLUMN activacion_pendiente BOOLEAN NOT NULL DEFAULT FALSE");const [[b]]=await pool.query("SELECT COUNT(*) n FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='ims_cm_archivo_legado' AND COLUMN_NAME='serie'");if(!Number(b.n))await pool.query("ALTER TABLE ims_cm_archivo_legado ADD COLUMN serie VARCHAR(255) NULL,ADD KEY ix_cm_serie_legado(archivo_drive,serie)");}
export async function fixtureCentro(pool,t,{apiPool=pool}={}){
 const erp=await fixtureERP(pool,t,{creacion:true});await pool.execute("INSERT INTO ims_cm_perfil(actor_id,rol) VALUES (?,'ADMIN')",[erp.actor]);for(const s of ['UIO','GYE'])await pool.execute('INSERT INTO ims_cm_acceso VALUES (?,?)',[erp.actor,s]);
 const carpeta=randomUUID();await pool.execute("INSERT INTO ims_cm_carpeta VALUES (?,NULL,'UIO','Carpeta sintética')",[carpeta]);
 const server=crearApi({pool:apiPool,publicUrl:ERP_ORIGIN,operacionNativa:true,centroHabilitado:true,gestorERP:erp.gestor,erpCreacion:true});await new Promise(r=>server.listen(0,'127.0.0.1',r));t.after(async()=>{server.closeAllConnections();await new Promise(r=>server.close(r));});
 const base='http://127.0.0.1:'+server.address().port,req=async(path,{method='GET',body,cookie,csrf,origin=ERP_ORIGIN}={})=>{const response=await fetch(base+path,{method,headers:{...(origin?{Origin:origin}:{}),...(body?{'Content-Type':'application/json'}:{}),...(cookie?{Cookie:cookie}:{}),...(csrf?{'X-IMS-CSRF':csrf}:{})},body:body?JSON.stringify(body):undefined});return {response,data:await response.json()};};
 const login=async()=>{const r=await req('/api/sesion',{method:'POST',body:{correo:erp.correo,contrasena:ERP_PASSWORD}});return {cookie:r.response.headers.get('set-cookie').split(';')[0],csrf:r.data.csrf};};
 const [[cli]]=await pool.execute("SELECT id,nombre FROM ims_op_cliente WHERE nombre='BELIA'");
 return {...erp,base,req,login,carpeta,cli,solicitud:{operacionId:randomUUID(),fuente:'CSV',sede:'UIO',codigo:'131126_'+randomUUID(),fechaInicio:'2026-11-13',carpetaId:carpeta,clientes:[cli.id],filas:[{numero:1,clienteId:cli.id,sku:'000123',depot:'2000.125',posicion:'A'}],vinculacion:'NUEVO',evento:{sede:'UIO',cliente:cli.nombre,titulo:'Conteo integrado',fechaInicio:'2026-11-13',responsableId:erp.actor,responsableNombre:'Revisor ERP'}}};
}
